using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Threading.Tasks;
using System.Windows;
using System.Windows.Controls;

namespace Ritm {
 public sealed partial class MainWindow {
  readonly Dictionary<string,DateTime> folderDue=new Dictionary<string,DateTime>();
  readonly HashSet<string> folderBusy=new HashSet<string>();
  readonly Dictionary<string,string> folderErrors=new Dictionary<string,string>();
  FolderWatchSettings FolderWatch(string name){FolderWatchSettings value;return store.Settings.FolderWatches!=null&&store.Settings.FolderWatches.TryGetValue(name,out value)?value:null;}
  void FolderWatchDialog(string name){
   var old=FolderWatch(name);var w=new Window{Owner=this,Title="Отслеживание папки · "+name,Width=500,SizeToContent=SizeToContent.Height,ResizeMode=ResizeMode.NoResize,WindowStartupLocation=WindowStartupLocation.CenterOwner,Background=UI.Canvas};var p=new StackPanel{Margin=new Thickness(24)};w.Content=p;
   p.Children.Add(UI.Text("Папка на сервере",16,null,true));UI.Gap(p,8);var path=UI.Input(old==null?"":old.Path,1024);p.Children.Add(path);var choose=UI.Button("Выбрать папку",()=>{using(var d=new System.Windows.Forms.FolderBrowserDialog()){d.Description="Выберите доступную папку на сервере";if(d.ShowDialog()==System.Windows.Forms.DialogResult.OK)path.Text=d.SelectedPath;}});choose.HorizontalAlignment=HorizontalAlignment.Left;p.Children.Add(choose);UI.Gap(p,12);p.Children.Add(UI.Text("Интервал проверки, минут (1–60)",12,UI.Muted));var interval=UI.Input((old==null?5:old.Minutes).ToString(),2);p.Children.Add(interval);UI.Gap(p,8);p.Children.Add(UI.Text("Проверяются также вложенные папки. При первом подключении создаётся исходный снимок.",11,UI.Muted));UI.Gap(p,12);
   p.Children.Add(UI.Button("Сохранить",()=>{int minutes;string dir=path.Text.Trim();if(!int.TryParse(interval.Text,out minutes)||minutes<1||minutes>60){MessageBox.Show(w,"Введите интервал от 1 до 60 минут.","Ритм");return;}if(!Directory.Exists(dir)){MessageBox.Show(w,"Папка недоступна. Укажите существующую локальную или сетевую папку.","Ритм");return;}if(store.Settings.FolderWatches==null)store.Settings.FolderWatches=new Dictionary<string,FolderWatchSettings>();bool same=old!=null&&string.Equals(old.Path,dir,StringComparison.OrdinalIgnoreCase);store.Settings.FolderWatches[name]=new FolderWatchSettings{Path=dir,Minutes=minutes,Snapshot=same?old.Snapshot:null,Log=same?old.Log:new List<string>()};store.SaveLocalPreferences();folderDue.Remove(name);folderErrors.Remove(name);w.DialogResult=true;},true));
   if(old!=null){var stop=UI.Button("Остановить отслеживание",()=>{store.Settings.FolderWatches.Remove(name);store.SaveLocalPreferences();folderDue.Remove(name);folderErrors.Remove(name);w.DialogResult=true;});stop.Margin=new Thickness(0,8,0,0);p.Children.Add(stop);}if(w.ShowDialog()==true){CheckFolders();Refresh();}
  }
  UIElement FolderWatchView(string name){var p=new StackPanel();p.Children.Add(UI.Text("Изменения в папке",14,null,true));var cfg=FolderWatch(name);if(cfg==null)p.Children.Add(UI.Text("Отслеживание папки не настроено.",11,UI.Muted));else{p.Children.Add(UI.Text(cfg.Path+" · каждые "+cfg.Minutes+" мин.",11,UI.Muted));string error;if(folderErrors.TryGetValue(name,out error))p.Children.Add(UI.Text("Ошибка проверки: "+error,11,UI.Muted));if(cfg.Log==null||cfg.Log.Count==0)p.Children.Add(UI.Text("Изменений пока нет.",11,UI.Muted));else foreach(string entry in GroupFolderLog(cfg.Log,cfg.Path))p.Children.Add(UI.Text(entry,12));}var card=UI.Card(p);card.Margin=new Thickness(0,14,0,0);return card;}
  static List<string> GroupFolderLog(IEnumerable<string> entries,string root){
   var lines=entries.ToList();var groups=new Dictionary<string,List<int>>(StringComparer.OrdinalIgnoreCase);var folders=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);
   for(int i=0;i<lines.Count;i++){string line=lines[i];int separator=line.IndexOf(" · ");if(separator<0)continue;string message=line.Substring(separator+3);string prefix=message.StartsWith("Добавлен: ")?"Добавлен: ":message.StartsWith("Изменён: ")?"Изменён: ":null;if(prefix==null)continue;string file=message.Substring(prefix.Length);string folder=Path.GetDirectoryName(file)??"";string key=line.Substring(0,separator)+"\u0001"+folder;List<int> group;if(!groups.TryGetValue(key,out group)){group=new List<int>();groups[key]=group;folders[key]=folder;}group.Add(i);}
   var replacements=new Dictionary<int,string>();var hidden=new HashSet<int>();foreach(var pair in groups){if(pair.Value.Count<2)continue;string folder=folders[pair.Key];if(folder=="")folder=Path.GetFileName(root.TrimEnd('\\'));string time=lines[pair.Value[0]].Substring(0,lines[pair.Value[0]].IndexOf(" · "));replacements[pair.Value[0]]=time+" · Изменения в папке: "+folder+" · файлов: "+pair.Value.Count;foreach(int index in pair.Value.Skip(1))hidden.Add(index);}
   var result=new List<string>();for(int i=0;i<lines.Count;i++){if(hidden.Contains(i))continue;string replacement;result.Add(replacements.TryGetValue(i,out replacement)?replacement:lines[i]);}return result;
  }
  static void LimitFolderLog(List<string> log,int limit){
   var groups=new HashSet<string>(StringComparer.OrdinalIgnoreCase);var kept=new List<string>();int index=0;
   foreach(string line in log){int separator=line.IndexOf(" · ");string message=separator<0?"":line.Substring(separator+3);string prefix=message.StartsWith("Добавлен: ")?"Добавлен: ":message.StartsWith("Изменён: ")?"Изменён: ":null;string key=prefix==null?"other\u0001"+(index++):line.Substring(0,separator)+"\u0001"+(Path.GetDirectoryName(message.Substring(prefix.Length))??"");if(groups.Contains(key)||groups.Count<limit){groups.Add(key);kept.Add(line);}}
   log.Clear();log.AddRange(kept);
  }
  static void RemoveDeletedFolderLogEntries(List<string> log,Dictionary<string,string> snapshot){
   var present=new HashSet<string>(snapshot.Keys,StringComparer.OrdinalIgnoreCase);
   log.RemoveAll(line=>{int separator=line.IndexOf(" · ");if(separator<0)return false;string message=line.Substring(separator+3);string prefix=message.StartsWith("Добавлен: ")?"Добавлен: ":message.StartsWith("Изменён: ")?"Изменён: ":null;return prefix!=null&&!present.Contains(message.Substring(prefix.Length));});
  }
  static Dictionary<string,string> ScanFolder(string root){root=Path.GetFullPath(root).TrimEnd('\\');if(!root.StartsWith(@"\\?\"))root=root.StartsWith(@"\\")?@"\\?\UNC\"+root.Substring(2):@"\\?\"+root;var result=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);var dirs=new Stack<string>();dirs.Push(root);while(dirs.Count>0){string dir=dirs.Pop();foreach(string file in Directory.GetFiles(dir)){var info=new FileInfo(file);if((info.Attributes&FileAttributes.ReparsePoint)!=0)continue;result[file.Substring(root.TrimEnd('\\').Length).TrimStart('\\')]=info.Length+":"+info.LastWriteTimeUtc.Ticks;}foreach(string sub in Directory.GetDirectories(dir)){if((File.GetAttributes(sub)&FileAttributes.ReparsePoint)==0)dirs.Push(sub);}}return result;}
  async void CheckFolders(){if(store.Settings.FolderWatches==null)return;foreach(var pair in store.Settings.FolderWatches.ToList()){string name=pair.Key;var cfg=pair.Value;if(cfg==null||string.IsNullOrWhiteSpace(cfg.Path)||folderBusy.Contains(name))continue;DateTime due;if(folderDue.TryGetValue(name,out due)&&DateTime.UtcNow<due)continue;folderBusy.Add(name);folderDue[name]=DateTime.UtcNow.AddMinutes(Math.Max(1,Math.Min(60,cfg.Minutes)));try{var snapshot=await Task.Run(()=>ScanFolder(cfg.Path));if(FolderWatch(name)!=cfg)continue;folderErrors.Remove(name);var changes=new List<string>();if(cfg.Snapshot!=null)foreach(var file in snapshot){string before;if(!cfg.Snapshot.TryGetValue(file.Key,out before))changes.Add("Добавлен: "+file.Key);else if(before!=file.Value)changes.Add("Изменён: "+file.Key);}cfg.Snapshot=snapshot;if(cfg.Log==null)cfg.Log=new List<string>();RemoveDeletedFolderLogEntries(cfg.Log,snapshot);string changeTime=DateTime.Now.ToString("dd.MM.yyyy HH:mm");foreach(string change in changes)cfg.Log.Insert(0,changeTime+" · "+change);LimitFolderLog(cfg.Log,50);store.SaveLocalPreferences();if(changes.Count>0){string target=name;notifier.Show(Notifications.FolderChanged,"Изменения в папке · "+ProjectDisplay(name),changes.Count==1?changes[0]:"Изменено или добавлено файлов: "+changes.Count,()=>{Go("board",target);gitView=true;Refresh();});}}catch(Exception e){if(FolderWatch(name)==cfg)folderErrors[name]=e.Message;}finally{folderBusy.Remove(name);if(project==name&&gitView)Refresh();}}}
 }
}
